"""Compare identical authored coordinates using actual full-foot probe results."""
from pathlib import Path
import argparse,collections,csv,gzip,hashlib,json
ROOT=Path(__file__).resolve().parents[1]
def load(folder):
 p=ROOT/folder/'current-flat-lanes.tsv';raw=p.read_bytes() if p.exists() else gzip.decompress(p.with_name(p.name+'.gz').read_bytes());rows=list(csv.DictReader(raw.decode('utf-8').splitlines(),delimiter='\t'));key=lambda r:tuple(r[k] for k in ['site','link','lane','x','y','z']);indexed={key(r):r for r in rows};assert len(indexed)==len(rows),'Ambiguous duplicate standing sample';return indexed,hashlib.sha256(raw).hexdigest()
def main():
 p=argparse.ArgumentParser();p.add_argument('--sites',nargs='+');p.add_argument('--before',type=Path,required=True);p.add_argument('--after',type=Path,required=True);p.add_argument('--output',type=Path,required=True);args=p.parse_args();a,ha=load(args.before);b,hb=load(args.after);a={k:r for k,r in a.items() if not args.sites or k[0] in args.sites};b={k:r for k,r in b.items() if not args.sites or k[0] in args.sites};assert a.keys()==b.keys(),'Coordinates changed: use a separately authored movement comparison instead of treating different samples as a regression control'
 regress=[dict(site=k[0],link=k[1],lane=k[2],point=k[3:],before_ground_y=a[k]['after_ground_y'],after_ground_y=b[k]['after_ground_y']) for k in a if a[k]['after_valid']=='true' and b[k]['after_valid']!='true'];recover=[dict(site=k[0],link=k[1],lane=k[2],point=k[3:]) for k in a if a[k]['after_valid']!='true' and b[k]['after_valid']=='true'];report=dict(status='FAIL_NEW_FULL_FOOT_STANDING_REGRESSIONS' if regress else 'PASS_UNCHANGED_COORDINATE_FULL_FOOTPRINT_REGRESSION',samples=len(a),before_decoded_sha256=ha,after_decoded_sha256=hb,regressions=regress,recovered=recover,recovered_by_site=dict(collections.Counter(r['site'] for r in recover)),scope='Exact same source positions/lanes/height, actual production standing footprints. Continuous complete routes and historical body-only tables remain separate.');dest=ROOT/args.output;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes((json.dumps(report,indent=2)+'\n').encode());print('UNCHANGED_FULL_FOOT',len(a),'samples;',len(recover),'recovered;',len(regress),'new invalid',flush=True);assert not regress,'New standing failures; actual source geometry must be repaired'
if __name__=='__main__':main()
